slides.example:
int level = 2;
switch (level)
{
    case 1:
        Console.WriteLine("Easy");
        break;
    case 2:
        Console.WriteLine("Medium");
        break;
}

int color = 1;
switch (color)
{
    case 1:
        Console.WriteLine("Red");
        break;
}

int pet = 3;
switch (pet)
{
    case 1:
        Console.WriteLine("Dog");
        break;
    default:
        Console.WriteLine("Other");
        break;
}

int day = 6;
switch (day)
{
    case 6:
    case 7:
        Console.WriteLine("Weekend");
        break;
    default:
        Console.WriteLine("Weekday");
}

int size = 2;
string label = size switch
{
    1 => "Small",
    2 => "Medium",
    _ => "Large"
};
Console.WriteLine(label);

object obj = 42;
string result = obj switch
{
    int i => $"int: {i}",
    string s => $"str: {s}",
    _ => "unknown"
};
Console.WriteLine(result);

int score = 85;
string grade = score switch
{
    int n when n >= 90 => "A",
    int n when n >= 80 => "B",
    _ => "C"
};
Console.WriteLine(grade);

